import json, random
HEX='0123456789abcdef'
def hx(n): return ''.join(r.choice(HEX) for _ in range(2*n))
def gen(seed):
    r = random.Random(seed)
    ntr = r.randint(1,4)
    traces=[]
    for ti in range(ntr):
        cfg = {
            'early': r.random()<0.5,
            'overlap': r.choice(['reject','first']),
            'buffer_packets': r.choice([0,1,2,1024]),
            'idle_ms': r.choice([0,1,2,3,7,50]),
            'max_streams_bidi': r.choice([0,1,2,8]),
            'max_streams_uni': r.choice([0,1,2,8]),
            'max_stream_data': r.choice([0,1,4,16]),
            'max_data': r.choice([0,2,7,64,10**12]),
            'crypto_limit': r.choice([0,1,8,64,65536]),
            'sent': {},
        }
        for lv in ('I','H','A'):
            ranges=[]; cur=r.choice([0,2,9])
            for _ in range(r.randint(0,6)):
                lo=cur+r.randint(0,2); hi=lo+r.randint(0,8); ranges.append([lo,hi]); cur=hi+r.randint(2,3)
            cfg['sent'][lv]=ranges
        nev=r.randint(2,25); events=[]; t=r.choice([0,0,1,1000000])
        for e in range(nev):
            t += r.choice([0,1,1,2,5,40])
            k=r.random()
            if k<0.22:
                events.append({'t':t,'op':'key','level':r.choice(['I','H','Z','A']),'action':r.choice(['install','discard'])})
            elif k<0.3:
                events.append({'t':t,'op':'tick'})
            else:
                size=r.choice([0,1199,1200,1201,2000])
                np_=r.randint(1,16)
                pkts=[]
                for i in range(np_):
                    lvl=r.choice(['I','H','Z','A','A','I','H'])
                    nf=r.randint(0,6); frames=[]
                    for j in range(nf):
                        ft=r.choice(['PADDING','PING','ACK','CRYPTO','STREAM','STREAM','STREAM','RESET_STREAM','STOP_SENDING','CLOSE','HANDSHAKE_DONE','UNKNOWN'])
                        if ft=='ACK':
                            nr=r.randint(0,4); ranges=[]; base=r.choice([0,1,5,20,10**6])
                            for q in range(nr):
                                lo=base+r.randint(0,3); hi=lo+r.randint(0,6); ranges.append([lo,hi]); base=hi+r.choice([0,1,2,9])
                            frames.append({'type':'ACK','ranges':ranges})
                        elif ft=='CRYPTO':
                            frames.append({'type':'CRYPTO','offset':r.choice([0,1,3,8,63,64,65,2**40]),'data_hex':hx(r.randint(0,6))})
                        elif ft=='STREAM':
                            frames.append({'type':'STREAM','id':r.choice([0,1,2,3,4,5,6,7,8,11,12,15,16,2**40]),'offset':r.choice([0,1,2,5,127,128,129,255,2**40]),'data_hex':hx(r.randint(0,5)),'fin':r.random()<0.4})
                        elif ft=='RESET_STREAM':
                            frames.append({'type':'RESET_STREAM','id':r.choice([0,1,2,3,4,7,8,12]),'final_size':r.choice([0,1,2,5,16,17,2**40])})
                        elif ft=='STOP_SENDING':
                            frames.append({'type':'STOP_SENDING','id':r.choice([0,1,2,3,4,8])})
                        elif ft=='CLOSE':
                            frames.append({'type':'CLOSE','app':r.random()<0.5,'code':r.choice([0,5,999999])})
                        else:
                            frames.append({'type':ft})
                    pkts.append({'level':lvl,'pn':r.choice([0,1,2,3,4,7,10**7]),'auth':r.random()<0.8,'frames':frames})
                events.append({'t':t,'op':'datagram','bytes':size,'packets':pkts})
        traces.append({'id':'tr%d'%ti,'config':cfg,'events':events})
    return {'version':1,'traces':traces}
EOF
